cd /tmp/sv-c0ec3e805d134e6a8802c86ed571115c/moderate-version-conflicts && dotnet package list --format json 2>/dev/null | python3 -m json.tool > after-cpm-packages.json && python3 -c "
import json
with open('baseline-packages.json') as f: base = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def pkg_map(data):
    m = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw.get('topLevelPackages', []):
                m[(name, pkg['id'])] = pkg['resolvedVersion']
    return m

b, a = pkg_map(base), pkg_map(after)
changes = [(k, b[k], a[k]) for k in b if b[k] != a.get(k)]
if changes:
    print('CHANGES:')
    for (proj, pkg), old, new in changes:
        print(f'  {proj} | {pkg}: {old} -> {new}')
else:
    print('No unexpected changes')

missing = set(b) - set(a)
added = set(a) - set(b)
if missing: print(f'MISSING: {missing}')
if added: print(f'ADDED: {added}')
"

